 "content": "from collections import deque


def transform(grid):
    """Color the 8-neighbor boundary of 1s: exterior as 2, enclosed as 3."""
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            adjacent = any(
                0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 1
                for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc
            )
            if adjacent:
                out[r][c] = 2 if outside[r][c] else 3
    return out
