    # Work per connected 1-component and color zeros within its one-cell expanded
    # bounding box. Enclosed zeros touching the component are 3; outer box is 2.
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=max(0,min(y for y,x in comp)-1); r1=min(h-1,max(y for y,x in comp)+1)
            c0=max(0,min(x for y,x in comp)-1); c1=min(w-1,max(x for y,x in comp)+1)
            # Identify enclosed background using 4-way flood fill within the component bbox.
            top=min(y for y,x in comp); bottom=max(y for y,x in comp)
            left=min(x for y,x in comp); right=max(x for y,x in comp)
            seen0=set(); q0=deque()
            for yy in range(top,bottom+1):
                for xx in (left,right):
                    if grid[yy][xx]==0 and (yy,xx) not in seen0:
                        seen0.add((yy,xx)); q0.append((yy,xx))
