def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top, bottom = min(y for y, x in comp), max(y for y, x in comp)
            left, right = min(x for y, x in comp), max(x for y, x in comp)

            # Find zero cells enclosed inside this component's bounding box.
            exterior = set()
            q0 = deque()
            for y in range(top, bottom + 1):
                for x in (left, right):
                    if grid[y][x] == 0 and (y, x) not in exterior:
                        exterior.add((y, x)); q0.append((y, x))
            for x in range(left, right + 1):
                for y in (top, bottom):
                    if grid[y][x] == 0 and (y, x) not in exterior:
                        exterior.add((y, x)); q0.append((y, x))
            while q0:
                y, x = q0.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if top <= ny <= bottom and left <= nx <= right and grid[ny][nx] == 0 and (ny, nx) not in exterior:
                        exterior.add((ny, nx)); q0.append((ny, nx))
            enclosed = [(y, x) for y in range(top, bottom + 1) for x in range(left, right + 1)
                        if grid[y][x] == 0 and (y, x) not in exterior]
            if not enclosed:
                continue

            # Closed loop: paint one-cell perimeter outside its bounding box 2.
            r0, r1 = max(0, top - 1), min(h - 1, bottom + 1)
            c0, c1 = max(0, left - 1), min(w - 1, right + 1)
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if grid[y][x] == 0 and (y == r0 or y == r1 or x == c0 or x == c1):
                        out[y][x] = 2
            # Outline the enclosed interior in 3, leaving its non-boundary center.
            for y, x in enclosed:
                if any(0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] == 1
                       for dy in (-1, 0, 1) for dx in (-1, 0, 1) if dy or dx):
