def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Enclosed background is found globally, so separate pieces cannot create
    # a false local cavity merely because they fall inside one bbox.
    exterior = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or c == 0 or r == h - 1 or c == w - 1):
                exterior[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not exterior[nr][nc]:
                exterior[nr][nc] = True
                q.append((nr, nc))
    interior = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == 0 and not exterior[r][c]}
    if not interior:
        return out

    # For every 1-component which borders an enclosed zero pocket, color its
    # full 8-neighbor contour: inner zeros 3, outer zeros 2.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = set()
            q1 = deque([(r, c)])
            seen.add((r, c))
            while q1:
                y, x = q1.popleft()
                comp.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q1.append((ny, nx))
            borders_interior = any(
                0 <= y + dy < h and 0 <= x + dx < w and (y + dy, x + dx) in interior
                for y, x in comp for dy in (-1, 0, 1) for dx in (-1, 0, 1) if dy or dx
            )
            if not borders_interior:
                continue
            for y, x in comp:
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if not (dy or dx):
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0:
                            out[ny][nx] = 3 if (ny, nx) in interior else 2
    return out
