    seen = set()
    # Work from each enclosed zero pocket; distinct shapes that jointly close
    # a pocket are handled together, while open shapes remain unchanged.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            pocket = set()
            q = deque([(r, c)])
            seen.add((r, c))
            leaks = False
            while q:
                y, x = q.popleft()
                pocket.add((y, x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    leaks = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) not in seen:
                        seen.add((ny,nx));q.append((ny,nx))
            if leaks:
                continue
            boundary=set()
            for y,x in pocket:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1:
                        boundary.add((ny,nx))
            if not boundary:
                continue
            # Identify all 1-components touching the pocket boundary.
            components=[]
            visited=set()
            for sy,sx in boundary:
                if (sy,sx) in visited: continue
                comp=set();q1=deque([(sy,sx)]);visited.add((sy,sx))
                while q1:
                    y,x=q1.popleft();comp.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in visited:
                            visited.add((ny,nx));q1.append((ny,nx))
                components.append(comp)
            wall=set().union(*components)
            # Mark inner contour and outer contour at the loop's pixel scale.
            for y,x in pocket:
                if any(0<=y+dy<h and 0<=x+dx<w and grid[y+dy][x+dx]==1
                       for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx):
