                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) not in pocket:
                            out[ny][nx]=2
            # The outer frame follows the bbox of the collective wall, with
            # segments interrupted where there is no adjacent enclosing wall.
            top,bottom=min(y for y,x in wall),max(y for y,x in wall)
            left,right=min(x for y,x in wall),max(x for y,x in wall)
